package org.stellar.sdk;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;

public class KeyPairTest {

    @Test
    public void canSign_NoValue_ReturnsFalse() {
        KeyPair keyPair = new KeyPair(null);
        assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeed_NoValue_ReturnsNull() {
        KeyPair keyPair = KeyPair.fromSecretSeed(null);
        assertNull(keyPair);
    }

    @Test
    public void fromAccountId_NoValue_ReturnsNull() {
        KeyPair keyPair = KeyPair.fromAccountId(null);
        assertNull(keyPair);
    }

    @Test
    public void random_NewKey() {
        KeyPair keyPair = KeyPair.random();
        assertNotNull(keyPair.getPublicKey());
    }

    @Test
    public void getPublicKeu_ExistingKey() {
        char[] secretSeed = "some_seed".toCharArray();
        KeyPair keyPair = new KeyPair(EdDSAPublicKey.fromSecretSeed(secretSeed));
        assertEquals(secretSeed, keyPair.getSecretSeed());
    }

    @Test
    public void sign_SignatureValid_ReturnsSignature() throws IOException {
        char[] secretSeed = "some_seed".toCharArray();
        Signature signature = Signature.getInstance("SHA256withEd25519");
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        XdrDataOutputStream out = new XdrDataOutputStream(bos);
        EdDSAPrivateKey privateKey = KeyPair.fromSecretSeed(secretSeed).getPrivateKey();
        signature.initSign(privateKey);
        signature.update(new Uint256(1));
        boolean success = signature.sign();
        assertTrue(success);
        byte[] signedBytes = bos.toByteArray();
        assertEquals(signature.getSignature(), signedBytes);
    }

    @Test
    public void verify_SignatureValid_ReturnsTrue() throws IOException {
        char[] secretSeed = "some_seed".toCharArray();
        Signature signature = Signature.getInstance("SHA256withEd25519");
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        XdrDataOutputStream out = new XdrDataOutputStream(bos);
        EdDSAPrivateKey privateKey = KeyPair.fromSecretSeed(secretSeed).getPrivateKey();
        signature.initSign(privateKey);
        signature.update(new Uint256(1));
        boolean success = signature.sign();
        assertTrue(success);
        byte[] signedBytes = bos.toByteArray();
        assertFalse(KeyPair.fromSecretSeed(secretSeed).verify(signedBytes, signature.getSignature()));
    }

    @Test
    public void getPublicKey_NoValue_ReturnsNull() {
        KeyPair keyPair = new KeyPair(null);
        assertNull(keyPair.getPublicKey());
    }
}
